// Numbers come from the ledger itself (the Invoice No column), not from a
// separate counter that can drift. Before anything is issued the existing
// numbers are audited: within each series they must run 1, 2, 3... with no
// gap and no repeat. If they don't, nothing is issued and you are alerted.

// ---- Your numbering format ----
const PREFIX = 'INV-';          // e.g. 'INV-' -> INV-2026-0001
const YEARLY_SERIES = true;     // restart at 1 every calendar year
const DIGITS = 4;               // zero padding
const READY = 'ready';          // Status value that means "issue this invoice"
// -------------------------------

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const year = new Date().getFullYear();
const seriesOf = y => (YEARLY_SERIES ? PREFIX + y + '-' : PREFIX);
const esc = s => s.replace(/[.*+?^\x24{}()|[\]\\]/g, '\\$&');
const pattern = new RegExp('^(' + esc(PREFIX) + (YEARLY_SERIES ? '(\\d{4})-' : '') + ')(\\d+)$');

const problems = [];
const bySeries = {};
for (const r of rows) {
  const no = String(r['Invoice No'] ?? '').trim();
  if (!no) continue;
  const m = no.match(pattern);
  if (!m) { problems.push('Row ' + r.row_number + ' has an invoice number in an unexpected format: ' + no); continue; }
  (bySeries[m[1]] ??= []).push({ n: Number(m[m.length - 1]), row: r.row_number, no });
}
for (const [series, list] of Object.entries(bySeries)) {
  const seen = new Map();
  for (const x of list) {
    if (seen.has(x.n)) problems.push(x.no + ' is used twice (rows ' + seen.get(x.n) + ' and ' + x.row + ')');
    else seen.set(x.n, x.row);
  }
  const max = Math.max(...seen.keys());
  const missing = [];
  for (let i = 1; i <= max; i++) if (!seen.has(i)) missing.push(series + String(i).padStart(DIGITS, '0'));
  if (missing.length) problems.push('Series ' + series + ' has gaps: ' + missing.slice(0, 10).join(', ') + (missing.length > 10 ? ' and ' + (missing.length - 10) + ' more' : ''));
}

if (problems.length) {
  return [{ json: { intact: false, problems } }];
}

// Money is computed in integer cents.
const cents = v => {
  const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? Math.round(n * 100) : NaN;
};

const series = seriesOf(year);
let next = Math.max(0, ...(bySeries[series] ?? []).map(x => x.n)) + 1;
const today = new Date();
const iso = d => d.toISOString().slice(0, 10);

const out = [];
for (const r of rows) {
  if (String(r['Invoice No'] ?? '').trim()) continue;
  if (String(r.Status ?? '').trim().toLowerCase() !== READY) continue;
  const qty = Number(r.Quantity ?? 1) || 1;
  const unit = cents(r['Unit price']);
  const rate = Number(String(r['Tax rate %'] ?? 0).replace('%', '')) || 0;
  const errs = [];
  if (!String(r.Client ?? '').trim()) errs.push('Client is empty');
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(r['Client email'] ?? '').trim())) errs.push('Client email is missing or invalid');
  if (!Number.isFinite(unit) || unit <= 0) errs.push('Unit price is missing or not a number');
  if (errs.length) { out.push({ json: { intact: true, skip: true, row_number: r.row_number, reason: errs.join('; ') } }); continue; }

  const subtotal = Math.round(qty * unit);
  const tax = Math.round(subtotal * rate / 100);
  const due = new Date(today); due.setDate(due.getDate() + (Number(r['Due in days']) || 14));
  const number = series + String(next++).padStart(DIGITS, '0');
  const money = c => (c / 100).toFixed(2);
  out.push({ json: {
    intact: true, skip: false, row_number: r.row_number,
    number, client: String(r.Client).trim(), email: String(r['Client email']).trim(),
    description: String(r.Description ?? '').trim(), quantity: qty,
    unitPrice: money(unit), subtotal: money(subtotal), taxRate: rate, tax: money(tax),
    total: money(subtotal + tax), currency: String(r.Currency ?? '').trim().toUpperCase() || 'USD',
    issued: iso(today), due: iso(due),
  } });
}
return out;

parameters.message:
=No invoices were issued, because the numbers already in your sheet don't form a clean sequence:

- {{ $json.problems.join('\n- ') }}

Fix the Invoice No column (restore the missing number, or record a voided invoice under it) and the next run will continue.
